"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";
import { LoaderCircle, Phone, Save, Search, Truck, X } from "lucide-react";
import { useAuth } from "../../context/AuthContext";

type Customer = { id: number; name: string; group?: string; mobile?: string; phone?: string; address?: string; description?: string; active?: boolean; [key: string]: unknown };
type ServiceRecord = { id: number; customerId?: number; customerName: string; phone?: string; serviceType?: string; date?: string; paymentStatus?: string };
type MapData = { customers: Customer[]; mobileServices: { records?: ServiceRecord[] } };
const phoneOf = (customer?: Customer) => customer?.mobile || customer?.phone || "";
const blankCustomer = (): Customer => ({ id: Date.now(), name: "", group: "خدمات سیار", mobile: "", phone: "", address: "", description: "", active: true });

export default function CustomerList() {
  const { user } = useAuth();
  const [data, setData] = useState<MapData>({ customers: [], mobileServices: { records: [] } });
  const [query, setQuery] = useState("");
  const [selected, setSelected] = useState<Customer | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const load = async () => {
    setLoading(true);
    try {
      const response = await fetch("/api/map-data", { cache: "no-store" });
      if (!response.ok) throw new Error();
      setData(await response.json() as MapData);
    } catch { setError("دریافت اطلاعات از دیتابیس ناموفق بود."); }
    finally { setLoading(false); }
  };
  useEffect(() => { if (user) void load(); }, [user]);
  const visible = useMemo(() => data.customers.filter((customer) => `${customer.name} ${phoneOf(customer)} ${customer.address || ""} ${customer.group || ""}`.includes(query.trim())), [data.customers, query]);
  const services = useMemo(() => (data.mobileServices.records || []).filter((record) => record.customerId === selected?.id || (record.customerName === selected?.name && record.phone === phoneOf(selected))), [data.mobileServices.records, selected]);
  const save = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!selected?.name.trim()) return;
    setSaving(true); setError("");
    try {
      const response = await fetch("/api/map-data", { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ section: "customer", data: selected }) });
      if (!response.ok) throw new Error();
      await load();
    } catch { setError("ذخیرهٔ مشتری در دیتابیس ناموفق بود."); }
    finally { setSaving(false); }
  };
  if (loading) return <div className="grid flex-1 place-items-center text-oxblood/60"><LoaderCircle className="animate-spin" /></div>;
  return <div className="flex min-h-0 flex-1 flex-col">
    <div className="flex items-center gap-2 rounded-xl border border-oxblood/12 bg-white px-3 py-2"><Search size={16} className="text-oxblood/55"/><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="جست‌وجوی مشتری…" className="min-w-0 flex-1 bg-transparent text-sm outline-none"/></div>
    <div className="mt-3 flex items-center justify-between text-xs text-oxblood/60"><span>{visible.length.toLocaleString("fa-IR")} مشتری</span>{user?.role === "admin" && <button onClick={() => setSelected(blankCustomer())} className="rounded-lg bg-oxblood px-2 py-1 font-bold text-white">+ مشتری</button>}</div>
    {error && <p className="mt-2 rounded-lg bg-red-50 p-2 text-xs text-red-700">{error}</p>}
    <div className="mt-3 min-h-0 flex-1 space-y-2 overflow-y-auto pb-3">{visible.map((customer) => <button key={customer.id} onClick={() => setSelected(customer)} className="w-full rounded-xl border border-oxblood/10 bg-white p-3 text-right transition hover:border-oxblood/35 hover:bg-blush"><b className="block text-sm text-oxblood-dark">{customer.name}</b><span className="mt-1 flex items-center gap-1 text-xs text-oxblood/60"><Phone size={12}/>{phoneOf(customer) || "بدون شماره"}</span><small className="mt-1 block truncate text-oxblood/45">{customer.group || "بدون گروه"} · {customer.address || "بدون آدرس"}</small></button>)}</div>
    {selected && <div className="fixed inset-0 z-30 flex items-end bg-oxblood-dark/35 sm:items-center sm:justify-center"><button className="absolute inset-0" onClick={() => setSelected(null)} aria-label="بستن"/><section className="relative max-h-[92vh] w-full overflow-y-auto rounded-t-3xl bg-paper p-5 shadow-2xl sm:max-w-xl sm:rounded-3xl"><div className="flex items-center justify-between"><h2 className="font-black text-oxblood">{selected.name || "مشتری جدید"}</h2><button onClick={() => setSelected(null)}><X/></button></div><form className="mt-4 grid gap-3 sm:grid-cols-2" onSubmit={save}>{[["name", "نام مشتری"], ["mobile", "موبایل"], ["phone", "تلفن"], ["group", "گروه"], ["address", "آدرس"], ["description", "توضیحات"]].map(([key, label]) => <label key={key} className={key === "address" || key === "description" ? "sm:col-span-2" : ""}><span className="mb-1 block text-xs font-bold text-oxblood/70">{label}</span><input value={String(selected[key] || "")} onChange={(event) => setSelected({ ...selected, [key]: event.target.value })} className="w-full rounded-xl border border-oxblood/15 bg-white px-3 py-2 text-sm outline-none focus:border-oxblood"/></label>)}<label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={selected.active !== false} onChange={(event) => setSelected({ ...selected, active: event.target.checked })} className="accent-oxblood"/>فعال</label>{user?.role === "admin" && <button disabled={saving} className="flex items-center justify-center gap-2 rounded-xl bg-oxblood px-4 py-2.5 font-bold text-white disabled:opacity-50"><Save size={16}/>{saving ? "در حال ذخیره…" : "ذخیره در دیتابیس"}</button>}</form><section className="mt-5 border-t border-oxblood/10 pt-4"><h3 className="flex items-center gap-2 text-sm font-black text-oxblood"><Truck size={16}/>سوابق خدمات سیار ({services.length.toLocaleString("fa-IR")})</h3>{services.length ? <div className="mt-2 space-y-2">{services.slice(0, 20).map((record) => <div key={record.id} className="rounded-lg bg-blush p-2 text-xs"><b>{record.serviceType || "خدمت"}</b><span className="mx-2">{record.date}</span><span>{record.paymentStatus === "settled" ? "تسویه" : "تسویه‌نشده"}</span></div>)}</div> : <p className="mt-2 text-xs text-oxblood/55">سابقه‌ای برای این مشتری ثبت نشده است.</p>}</section></section></div>}
  </div>;
}
